def hamza_dual(e):
    """a hamza-final stem before the dual's alif is written with madda (أَلْجَآ، أَظْمَآ)"""
    for k in ("mazi", "mudari", "amr"):
        e[k] = [c.replace("أَا", "آ").replace("ئَا", "آ") if c.endswith("أَا") or c.endswith("ئَا") else c for c in e[k]]
    return e
